val localKonanDir = project.provider {
    File(System.getenv("KONAN_DATA_DIR") ?: (System.getProperty("user.home") + File.separator + ".konan"))
}

val dependencyDllFiles = project.provider {
    localKonanDir.get()
        .also {
            logger.lifecycle("listing $it")
            logger.lifecycle(it.listFilesOrdered { true }.joinToString("\n"))
        }
        .resolve("dependencies")
//            .also { print(it.listFiles().joinToString("\n")) }
        .listFilesOrdered { it.isDirectory && it.name.startsWith("msys2-mingw") }
        .firstOrNull()// ?: error("cannot find msys2-mingw in konan dir ${localKonanDir.get()}")
        ?.let { msys2Mingw ->
            msys2Mingw.resolve("bin").listFilesOrdered { f ->
                f.extension == "dll" &&
                        f.nameWithoutExtension.startsWith("libstdc++") ||
                        f.nameWithoutExtension.startsWith("libgcc_s_seh") ||
                        f.nameWithoutExtension.startsWith("libwinpthread")
            }
        }.orEmpty()
}

val mingwDownloadDest = layout.buildDirectory.file("download/msys2-mingw-w64-x86_64-2.zip")

tasks {
    val downloadMsys2Mingw by registering(Download::class) {
        group = "package"
        src("https://download.jetbrains.com/kotlin/native/msys2-mingw-w64-x86_64-2.zip")
        dest(mingwDownloadDest)
        overwrite(false)
    }
    val unzipDependencyDlls by registering(Copy::class) {
        group = "package"

        dependsOn(downloadMsys2Mingw)
        from(
            zipTree(downloadMsys2Mingw.get().dest)
                .filter { f ->
                    f.parentFile.name == "bin" &&
                            f.extension == "dll" &&
                            listOf(
                                "libstdc++",
                                "libgcc_s_seh",
                                "libwinpthread",
                            ).any {
                                f.nameWithoutExtension.startsWith(it)
                            }
                }
        )
        into(layout.buildDirectory.file("dependencies"))
    }
//    val packageDependencies by registering(Zip::class) {
